begin;
select no_plan();
insert into auth.users(id,raw_user_meta_data) select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'{}' from generate_series(51,54) n;
set local request.jwt.claims='{"sub":"00000000-0000-0000-0000-000000000051","role":"authenticated"}';
select public.create_household('80000000-0000-0000-0000-000000000001','Inventory kitchen');
insert into public.household_members(household_id,user_id,role,slot) values('80000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000052','member',2);
create temp table inventory_fixture(payload jsonb,lot jsonb);
insert into inventory_fixture(payload) values('{"requestId":"90000000-0000-0000-0000-000000000001","ingredientId":"60000000-0000-0000-0000-000000000001","quantity":0.5,"unit":"kg","storageLocation":"fridge","confidence":"confirmed","expiryDate":"2026-11-05","expiryKind":"use_by","note":"one pack"}');
grant all on inventory_fixture to authenticated;
set local role authenticated;
select is(jsonb_array_length(public.search_inventory_ingredients('chicken breasts')),1,'aliases resolve canonical ingredient');
select is(jsonb_array_length(public.search_inventory_ingredients('basmati')),1,'varieties remain distinct');
select is(jsonb_array_length(public.search_inventory_ingredients('%')),0,'search uses literal text');
update inventory_fixture set lot=public.add_inventory_lot('80000000-0000-0000-0000-000000000001',payload);
select is((select (lot->>'quantityBase')::numeric from inventory_fixture),500::numeric,'kilograms normalize to grams');
select is((select lot->>'expirySource' from inventory_fixture),'packaging','confirmed date provenance');
select is((select lot->>'expiryDate' from inventory_fixture),'2026-11-05','date retained exactly');
select is((select lot->>'version' from inventory_fixture),'1','initial version');
select is(jsonb_array_length(public.list_inventory_lots('80000000-0000-0000-0000-000000000001')),1,'household sees lot');
select is((select public.add_inventory_lot('80000000-0000-0000-0000-000000000001',payload)->>'id' from inventory_fixture),(select lot->>'id' from inventory_fixture),'same request safely replays');
select is((select count(*) from public.inventory_transactions)::integer,1,'retry creates no duplicate ledger');
select throws_ok($$select public.add_inventory_lot('80000000-0000-0000-0000-000000000001',payload||'{"quantity":1}') from inventory_fixture$$,'40001',null,'same request different payload rejected');
select throws_ok($$insert into public.inventory_lots(id) values(gen_random_uuid())$$,'42501',null,'direct lot insert forbidden');
select throws_ok($$update public.inventory_lots set confidence='estimated'$$,'42501',null,'direct lot update forbidden');
select throws_ok($$insert into public.inventory_transactions(id) values(gen_random_uuid())$$,'42501',null,'direct ledger insert forbidden');
select throws_ok($$update public.inventory_transactions set reason='forged'$$,'42501',null,'direct ledger rewrite forbidden');
select throws_ok($$delete from public.inventory_transactions$$,'42501',null,'direct ledger deletion forbidden');
select throws_ok($$select * from private.inventory_requests$$,'42501',null,'request snapshots are private');
select throws_ok($$select public.add_inventory_lot('80000000-0000-0000-0000-000000000001',payload||'{"requestId":"90000000-0000-0000-0000-000000000002","unit":"ml"}') from inventory_fixture$$,'22023',null,'mass-volume conversions forbidden');
select throws_ok($$select public.add_inventory_lot('80000000-0000-0000-0000-000000000001',payload||'{"requestId":"90000000-0000-0000-0000-000000000002","quantity":-1}') from inventory_fixture$$,'22023',null,'negative addition forbidden');
select throws_ok($$select public.add_inventory_lot('80000000-0000-0000-0000-000000000001',payload||'{"requestId":"90000000-0000-0000-0000-000000000002","quantity":0.0001}') from inventory_fixture$$,'22023',null,'precision cannot silently round');
select throws_ok($$select public.add_inventory_lot('80000000-0000-0000-0000-000000000001',payload||'{"requestId":"90000000-0000-0000-0000-000000000002","expiryDate":"2026-02-30"}') from inventory_fixture$$,'22023',null,'invalid calendar date rejected');
select throws_ok($$select public.add_inventory_lot('80000000-0000-0000-0000-000000000001',payload||'{"requestId":"90000000-0000-0000-0000-000000000002","storageLocation":null}') from inventory_fixture$$,'22023',null,'JSON null cannot bypass validation');
select throws_ok($$select public.add_inventory_lot('80000000-0000-0000-0000-000000000001',payload||'{"requestId":"90000000-0000-0000-0000-000000000002","expiryKind":null}') from inventory_fixture$$,'22023',null,'date without provenance rejected');
select is((select count(*) from public.inventory_transactions)::integer,1,'invalid attempts have no ledger effects');
set local request.jwt.claims='{"sub":"00000000-0000-0000-0000-000000000052","role":"authenticated"}';
select is(jsonb_array_length(public.list_inventory_lots('80000000-0000-0000-0000-000000000001')),1,'second member reads same stock');
select throws_ok($$select public.add_inventory_lot('80000000-0000-0000-0000-000000000001',payload) from inventory_fixture$$,'40001',null,'another member cannot replay caller request');
update inventory_fixture set lot=public.adjust_inventory_lot('80000000-0000-0000-0000-000000000001',jsonb_build_object('requestId','90000000-0000-0000-0000-000000000003','lotId',lot->>'id','expectedVersion',1,'quantityBase',300,'confidence','estimated','reason','Used some elsewhere'));
select is((select (lot->>'quantityBase')::numeric from inventory_fixture),300::numeric,'correction sets requested absolute remaining stock');
select is((select (lot->>'originalQuantityBase')::numeric from inventory_fixture),500::numeric,'original quantity preserved');
select is((select quantity_delta_base from public.inventory_transactions where source_type='manual_adjustment'),(-200)::numeric,'correction writes delta instead of rewriting stock');
select is((select actor_user_id from public.inventory_transactions where source_type='manual_adjustment'),'00000000-0000-0000-0000-000000000052'::uuid,'actor is caller not owner');
select throws_ok($$select public.adjust_inventory_lot('80000000-0000-0000-0000-000000000001',jsonb_build_object('requestId','90000000-0000-0000-0000-000000000004','lotId',lot->>'id','expectedVersion',1,'quantityBase',100,'confidence','confirmed','reason','Stale correction')) from inventory_fixture$$,'40001',null,'stale correction cannot overwrite newer stock');
update inventory_fixture set lot=public.freeze_inventory_lot('80000000-0000-0000-0000-000000000001',jsonb_build_object('requestId','90000000-0000-0000-0000-000000000005','lotId',lot->>'id','expectedVersion',2));
select is((select lot->>'storageLocation' from inventory_fixture),'freezer','explicit freezing moves location');
select ok((select lot->>'frozenAt' is not null from inventory_fixture),'freeze time recorded');
select is((select lot->>'expiryDate' from inventory_fixture),'2026-11-05','freezing retains original date');
select is((select lot->>'expiryKind' from inventory_fixture),'use_by','freezing preserves original kind');
select is((select lot->>'confidence' from inventory_fixture),'estimated','freeze preserves stock uncertainty');
select is((select (lot->>'quantityBase')::numeric from inventory_fixture),300::numeric,'freezing does not consume');
select is((select quantity_delta_base from public.inventory_transactions where source_type='freeze'),0::numeric,'freeze has zero ledger delta');
select is(jsonb_array_length(public.get_inventory_history('80000000-0000-0000-0000-000000000001',(select (lot->>'id')::uuid from inventory_fixture))),3,'audit history contains add correction and freeze');
update inventory_fixture set lot=public.adjust_inventory_lot('80000000-0000-0000-0000-000000000001',jsonb_build_object('requestId','90000000-0000-0000-0000-000000000006','lotId',lot->>'id','expectedVersion',3,'quantityBase',0,'confidence','confirmed','reason','Finished the pack'));
select is((select (lot->>'quantityBase')::numeric from inventory_fixture),0::numeric,'zero stock retained with ledger history');
select is((select count(*) from public.inventory_lots)::integer,1,'empty lot is not deleted');
set local request.jwt.claims='{"sub":"00000000-0000-0000-0000-000000000053","role":"authenticated"}';
select is((select count(*) from public.inventory_lots)::integer,0,'nonmember RLS hides lots');
select is((select count(*) from public.inventory_transactions)::integer,0,'nonmember RLS hides ledger');
select throws_ok($$select public.list_inventory_lots('80000000-0000-0000-0000-000000000001')$$,'42501',null,'nonmember RPC read rejected');
select throws_ok($$select public.add_inventory_lot('80000000-0000-0000-0000-000000000001',payload) from inventory_fixture$$,'42501',null,'nonmember write rejected');
select throws_ok($$select public.get_inventory_history('80000000-0000-0000-0000-000000000001',(select (lot->>'id')::uuid from inventory_fixture))$$,'42501',null,'nonmember history rejected');
reset role;
select throws_ok($$update public.inventory_transactions set reason='rewritten' where source_type='manual_add'$$,'23514','Inventory history is immutable','trusted paths cannot rewrite ledger either');
set local request.jwt.claims='{"sub":"00000000-0000-0000-0000-000000000051","role":"authenticated"}';
select public.archive_household('80000000-0000-0000-0000-000000000001');
set local role authenticated;
select throws_ok($$select public.list_inventory_lots('80000000-0000-0000-0000-000000000001')$$,'42501',null,'archived household inaccessible');
select throws_ok($$select public.add_inventory_lot('80000000-0000-0000-0000-000000000001',payload) from inventory_fixture$$,'42501',null,'archived household retry cannot revive inventory');
reset role;
set local role anon;
select throws_ok($$select public.list_inventory_lots('80000000-0000-0000-0000-000000000001')$$,'42501',null,'anonymous read forbidden');
select throws_ok($$select public.search_inventory_ingredients('')$$,'42501',null,'anonymous catalogue RPC forbidden');
reset role;
set constraints all immediate;
select * from finish();
rollback;
